p='make_deck.js'; s=open(p,encoding='utf-8').read()
def rep(a,b):
    global s
    assert a in s, a
    s=s.replace(a,b,1)
rep('fontSize: 32, bold: true, color: C.text1','fontSize: 30, bold: true, color: C.text1')
rep('fontSize: 32, bold: true, color: C.background1, margin: 0','fontSize: 30, bold: true, color: C.background1, margin: 0')
rep('"Literature: strong pieces, no quote-backed audit at reading time"','"Literature: no quote-backed audit at reading time"')
rep('"Our earlier density signal did not generalise, so we changed the question"','"Earlier density signal did not generalise"')
rep('"Implementation: a working Chrome extension on a FastAPI backend"','"Working Chrome extension on a FastAPI backend"')
rep('"Validation setup and confusion matrices on 100 FEVER claims"','"Confusion matrices on 100 balanced FEVER claims"')
rep('"Results: Wikipedia helped decisive claims; pooled never abstained"','"Results: retrieval helped, pooled never abstained"')
rep('"Comparative analysis: retrieval mattered more than the rule"','"Comparison: retrieval mattered more than the rule"')
rep('{ x: 8.55, y: 2.45, w: 3.8, h: 3.9, fontSize: 16, color: C.background1 }','{ x: 8.55, y: 2.45, w: 3.8, h: 3.9, fontSize: 18, color: C.background1 }')
rep("T(s, body, { x: x + 0.15, y: 3.05, w: bw - 0.3, h: 1.6, fontSize: 14 });","T(s, body, { x: x + 0.15, y: 3.05, w: bw - 0.3, h: 1.6, fontSize: 15 });")
rep('"kNN and Mahalanobis density"','"kNN + Mahalanobis"')
rep('"Confusion matrix, macro-F1"','"Confusion, macro-F1"')
rep('["34", "paper checks pass; 0 counterexamples"]','["34", "paper tests pass; no counterexample found"]')
rep("{ x: x + 0.25, y: 2.25, w: 3.6, h: 2.6, fontSize: 14 }","{ x: x + 0.25, y: 2.25, w: 3.6, h: 2.6, fontSize: 15 }")
rep('rowH: 0.62, border: { type: "solid", pt: 0.75, color: "FFFFFF" }','rowH: 0.72, border: { type: "solid", pt: 0.75, color: "FFFFFF" }')
rep("{ x: 0.6, y: 6.1, w: 12.1, h: 0.5, fontSize: 12, color: C.accent4 }","{ x: 0.6, y: 6.5, w: 12.1, h: 0.45, fontSize: 12, color: C.accent4 }")
rep('x: 0.6, y: 1.55, w: 6.5, h: 4.15, barDir: "col", barGrouping','x: 0.6, y: 1.55, w: 5.6, h: 4.15, barDir: "col", barGrouping')
rep("{ x: 7.35, y: 1.6, w: 5.35, colW: [1.35, 1.2, 0.7, 1.2, 0.9], rowH: 0.78,","{ x: 6.5, y: 1.6, w: 6.2, colW: [1.3, 1.55, 0.8, 1.55, 1.0], rowH: 0.78,")
rep("{ x: 7.35, y: 4.8, w: 5.35, h: 0.5, fontSize: 12, color: C.accent4 }","{ x: 6.5, y: 4.8, w: 6.2, h: 0.5, fontSize: 12, color: C.accent4 }")
rep('"NEI recall: pooled score vs per-source stance"','"NEI recall: pooled score vs stance variant"')
rep("T(s, body, { x: x + 0.25, y: 2.95, w: 3.4, h: 1.45, fontSize: 14 });","T(s, body, { x: x + 0.25, y: 2.95, w: 3.4, h: 1.45, fontSize: 16 });")
rep('{ x: 0.6, y: 1.6, w: 12.1, h: 0.9, fontSize: 24, bold: true, color: C.accent1, fontFace: FORM, valign: "middle" }','{ x: 0.6, y: 1.6, w: 12.1, h: 0.9, fontSize: 22, bold: true, color: C.accent1, fontFace: FORM, valign: "middle" }')
rep('"Calibrate with conformal prediction"','"Fit the conformal calibration interface (not fitted today)"')
rep("{ x: x + 0.3, y: 3.6, w: 5.4, h: 2.4, fontSize: 15, color: C.background1 }","{ x: x + 0.3, y: 3.6, w: 5.4, h: 2.4, fontSize: 16, color: C.background1 }")
